WITH filtered AS (SELECT *, CEIL(sqft) AS sqft_whole, COALESCE(region, 'UNKNOWN') AS region_clean FROM stores WHERE opened_date >= DATE '2023-08-18' AND region IS NOT NULL), metrics AS (SELECT *, LAG(sqft) OVER w_recent AS prev_sqft, LAG(sqft_whole) OVER w_recent AS prev_sqft_whole, LEAD(sqft_whole) OVER w_recent AS next_sqft_whole, ROW_NUMBER() OVER w_recent AS event_seq FROM filtered WINDOW w_recent AS (PARTITION BY region ORDER BY opened_date, id)), with_last AS (SELECT s.*, x.order_date, x.shipping_fee FROM metrics s JOIN LATERAL (SELECT c.order_date, c.shipping_fee FROM orders c WHERE c.store_id = s.id ORDER BY c.discount DESC, c.id DESC LIMIT 1) x ON TRUE), latest_match AS (SELECT s.*, x.order_channel FROM with_last s LEFT JOIN LATERAL (SELECT c.channel AS order_channel FROM orders c WHERE c.store_id = s.id ORDER BY c.shipping_fee DESC, c.id DESC LIMIT 1) x ON TRUE), deduped AS (SELECT id, store_name, city, opened_date, prev_sqft_whole, next_sqft_whole, event_seq, shipping_fee, order_channel FROM latest_match QUALIFY ROW_NUMBER() OVER (PARTITION BY order_channel ORDER BY event_seq DESC NULLS LAST, id) = 1) SELECT id, opened_date, prev_sqft_whole, next_sqft_whole, event_seq, shipping_fee FROM deduped ORDER BY shipping_fee NULLS FIRST
